concepts.code:
// A tiny graph, written as Cypher patterns:
//
//   (:Person {name: 'Ann'})-[:FOLLOWS {since: 2021}]->(:Person {name: 'Bob'})
//   (:Person {name: 'Bob'})-[:WORKS_AT]->(:Company {name: 'Acme'})
//
// nodes:          (variable:Label {property: value})
// relationships:  -[variable:TYPE {property: value}]->
//
// Ann  --FOLLOWS-->  Bob  --WORKS_AT-->  Acme
RETURN 'nodes, relationships, labels, types, properties' AS model;

// three people, a company, and who follows whom
CREATE (ann:Person {name: 'Ann', born: 1990}),
       (bob:Person {name: 'Bob', born: 1985}),
       (cy:Person  {name: 'Cy',  born: 2001}),
       (acme:Company {name: 'Acme'}),
       (ann)-[:FOLLOWS {since: 2021}]->(bob),
       (cy)-[:FOLLOWS {since: 2023}]->(bob),
       (bob)-[:WORKS_AT]->(acme);

// connect existing nodes: MATCH them, then CREATE the relationship
MATCH (a:Person {name: 'Ann'}), (c:Person {name: 'Cy'})
CREATE (a)-[:FOLLOWS {since: 2024}]->(c);
// Added 1 relationship, set 1 property

// who does each person follow, oldest followers first
MATCH (p:Person)-[f:FOLLOWS]->(other:Person)
WHERE f.since >= 2021
RETURN p.name AS follower, other.name AS follows, f.since AS since
ORDER BY p.born, since;
// follower | follows | since
// "Ann"    | "Bob"   | 2021
// "Ann"    | "Cy"    | 2024
// "Cy"     | "Bob"   | 2023

// either direction: everyone connected to Bob by FOLLOWS
MATCH (:Person {name: 'Bob'})-[:FOLLOWS]-(x:Person)
RETURN collect(x.name) AS connected;   // ["Ann", "Cy"] (order may vary)

// recommend people to Ann: followed by people she follows, not yet followed
MATCH (me:Person {name: 'Ann'})-[:FOLLOWS]->(:Person)-[:FOLLOWS]->(fof:Person)
WHERE fof <> me AND NOT (me)-[:FOLLOWS]->(fof)
RETURN fof.name AS suggestion, count(*) AS via
ORDER BY via DESC;

// everyone, with their employer if any
MATCH (p:Person)
OPTIONAL MATCH (p)-[:WORKS_AT]->(c:Company)
RETURN p.name, c.name AS company;
// "Ann" null | "Bob" "Acme" | "Cy" null

// the most followed people, with up to 3 of their followers' names
MATCH (p:Person)<-[:FOLLOWS]-(f:Person)
WITH p, count(f) AS followers, collect(f.name)[..3] AS sample
WHERE followers >= 2                       // filter on the aggregate
RETURN p.name, followers, sample
ORDER BY followers DESC;
// "Bob" | 2 | ["Ann", "Cy"]

// average birth year per company (grouping key: c.name)
MATCH (p:Person)-[:WORKS_AT]->(c:Company)
RETURN c.name AS company, avg(p.born) AS avgBorn, count(*) AS staff;

CREATE CONSTRAINT person_email IF NOT EXISTS
FOR (p:Person) REQUIRE p.email IS UNIQUE;

CREATE INDEX person_name IF NOT EXISTS
FOR (p:Person) ON (p.name);

CREATE TEXT INDEX company_name_text IF NOT EXISTS
FOR (c:Company) ON (c.name);

SHOW INDEXES YIELD name, type, labelsOrTypes, properties, state;
// "person_email"      RANGE ["Person"]  ["email"] "ONLINE"   (backs the constraint)
// "person_name"       RANGE ["Person"]  ["name"]  "ONLINE"
// "company_name_text" TEXT  ["Company"] ["name"]  "ONLINE"

MERGE (p:Person {email: 'ann@example.com'})   // now safe under concurrency
SET p.name = 'Ann';

// people.csv:  email,name,born
// follows.csv: from,to,since
CREATE CONSTRAINT person_email IF NOT EXISTS
FOR (p:Person) REQUIRE p.email IS UNIQUE;

LOAD CSV WITH HEADERS FROM 'file:///people.csv' AS row
CALL (row) {
  MERGE (p:Person {email: row.email})
  SET p.name = row.name, p.born = toInteger(row.born)
} IN TRANSACTIONS OF 10000 ROWS;

LOAD CSV WITH HEADERS FROM 'file:///follows.csv' AS row
CALL (row) {
  MATCH (a:Person {email: row.from}), (b:Person {email: row.to})
  MERGE (a)-[f:FOLLOWS]->(b)
  SET f.since = toInteger(row.since)
} IN TRANSACTIONS OF 10000 ROWS;

// everyone Ann can reach in 1 to 3 FOLLOWS hops, with the distance
MATCH p = (:Person {name: 'Ann'})-[:FOLLOWS]->{1,3}(x:Person)
RETURN x.name, min(length(p)) AS hops
ORDER BY hops;

// the shortest connection between Ann and Dan, any direction
MATCH p = SHORTEST 1 (a:Person {name: 'Ann'})-[:FOLLOWS]-+(d:Person {name: 'Dan'})
RETURN [n IN nodes(p) | n.name] AS route, length(p) AS hops;

// management chain upward, at most 10 levels
MATCH (e:Employee {name: 'Cy'})-[:REPORTS_TO]->{1,10}(boss:Employee)
RETURN collect(boss.name) AS chain;

// batch write from a parameter list (driver passes $rows)
UNWIND $rows AS row
MERGE (p:Person {email: row.email})
SET p.name = row.name;

// per person: follower count, whether at Acme, top 2 followees by name
MATCH (p:Person)
RETURN p.name,
       COUNT { (p)<-[:FOLLOWS]-() } AS followers,
       EXISTS { (p)-[:WORKS_AT]->(:Company {name: 'Acme'}) } AS atAcme,
       COLLECT { MATCH (p)-[:FOLLOWS]->(f) RETURN f.name ORDER BY f.name LIMIT 2 } AS follows;

// top follower per company with a CALL subquery
MATCH (c:Company)
CALL (c) {
  MATCH (c)<-[:WORKS_AT]-(e)<-[:FOLLOWS]-(fan)
  RETURN fan.name AS topFan, count(*) AS n ORDER BY n DESC LIMIT 1
}
RETURN c.name, topFan, n;

// before: skills as a list property, "who shares a skill" needs a scan
// (:Person {name: 'Ann', skills: ['cypher', 'python']})

// refactor: promote each skill to a node
MATCH (p:Person) WHERE p.skills IS NOT NULL
UNWIND p.skills AS skill
MERGE (s:Skill {name: skill})
MERGE (p)-[:HAS_SKILL]->(s)
REMOVE p.skills;

// now a short traversal
MATCH (:Person {name: 'Ann'})-[:HAS_SKILL]->(s)<-[:HAS_SKILL]-(peer)
RETURN peer.name, collect(s.name) AS shared
ORDER BY size(shared) DESC;

PROFILE
MATCH (p:Person {name: 'Ann'})-[:FOLLOWS]->(f)-[:WORKS_AT]->(c:Company)
RETURN c.name, count(*) AS n;

// Before an index exists (read bottom-up):
//   NodeByLabelScan  p:Person          rows 1000000   db hits 1000001
//   Filter           p.name = $autostring_0  rows 1
//   Expand(All)      (p)-[:FOLLOWS]->(f)
//   ...
CREATE INDEX person_name IF NOT EXISTS FOR (p:Person) ON (p.name);
// After:
//   NodeIndexSeek    p:Person(name)    rows 1         db hits 2

// 1. project Person nodes and FOLLOWS relationships into memory
CALL gds.graph.project('social', 'Person', 'FOLLOWS');

// 2. stream PageRank scores: most influential people first
CALL gds.pageRank.stream('social')
YIELD nodeId, score
RETURN gds.util.asNode(nodeId).name AS name, round(score, 3) AS score
ORDER BY score DESC LIMIT 5;

// 3. find communities and store them on the nodes
CALL gds.louvain.write('social', {writeProperty: 'community'})
YIELD communityCount, modularity;

// 4. free the memory
CALL gds.graph.drop('social');
